package com.nexamart.backend.domain;
import jakarta.persistence.*;import java.time.Instant;
@Entity @Table(name="notifications",indexes=@Index(name="idx_notifications_user",columnList="user_id,read_flag")) public class Notification{@Id@GeneratedValue(strategy=GenerationType.IDENTITY)private Long id;@ManyToOne(optional=false)private UserAccount user;private String title;@Column(length=1000)private String message;private Instant createdAt=Instant.now();@Column(name="read_flag")private boolean readFlag=false;@Enumerated(EnumType.STRING)private NotificationType type;private Long orderId;private String actionUrl;public Long getId(){return id;}public UserAccount getUser(){return user;}public void setUser(UserAccount v){user=v;}public String getTitle(){return title;}public void setTitle(String v){title=v;}public String getMessage(){return message;}public void setMessage(String v){message=v;}public Instant getCreatedAt(){return createdAt;}public boolean isReadFlag(){return readFlag;}public void setReadFlag(boolean v){readFlag=v;}public NotificationType getType(){return type;}public void setType(NotificationType v){type=v;}public Long getOrderId(){return orderId;}public void setOrderId(Long v){orderId=v;}public String getActionUrl(){return actionUrl;}public void setActionUrl(String v){actionUrl=v;}}
